<template>  <div class="auth-card">    <h1>Зміна пароля</h1>    <form @submit.prevent="submit">      <label>        Новий пароль        <input v-model="password" type="password" placeholder="********" required />      </label>      <label>        Підтвердження пароля        <input v-model="confirm" type="password" placeholder="********" required />      </label>      <p v-if="error" class="error">{{ error }}</p>      <p v-if="ok" class="ok">Пароль змінено. Можете увійти.</p>      <button type="submit" class="primary">Змінити пароль</button>    </form>    <div class="links">      <RouterLink to="/login">Перейти до входу</RouterLink>    </div>  </div></template><script setup>import { ref, onMounted } from 'vue'import { useRoute, useRouter } from 'vue-router'import { confirmPasswordReset, authError } from '@/stores/auth'const route = useRoute()const router = useRouter()const token = ref('')const password = ref('')const confirm = ref('')const ok = ref(false)const error = authErroronMounted(() => {  token.value = String(route.query.token || '')})async function submit() {  const success = await confirmPasswordReset(token.value, password.value, confirm.value)  if (success) {    ok.value = true  }}</script><style scoped>.auth-card { max-width: 480px; margin: 8vh auto; padding:1.25rem; background:#fff; border:1px solid #e5e7eb; border-radius:10px; box-shadow:0 6px 24px rgba(0,0,0,.08); color: #111111 }label { display:block; margin: .75rem 0; font-weight: 600; }input { width:100%; padding:.6rem .7rem; border:1px solid #d1d5db; border-radius:8px; margin-top:.35rem; }button.primary { width:100%; margin-top:1rem; padding:.6rem .7rem; background:#3b82f6; color:#fff; border:none; border-radius:8px; cursor:pointer; }button.primary:hover { background:#2563eb; }.error { color:#b91c1c; margin-top:.5rem; }.ok { color:#059669; margin-top:.5rem; }</style>